import { describe, expect, it } from 'vitest'
import type { AdmittedPromptContentPart } from '@deepseek-ai/dsh-attachment'
import { expandChatAttachments } from '../src/chat-attachments.ts'

const file = (): AdmittedPromptContentPart => ({ type: 'file', attachment: { name: 'notes.txt' } } as AdmittedPromptContentPart)
function store(...chunks: Uint8Array[]) {
  return { async *readFileStream() { yield* chunks } }
}

describe('Chat attachment admission', () => {
  it('decodes split UTF-8 chunks and preserves the durable attachment reference', async () => {
    const bytes = new TextEncoder().encode('你好，Chat')
    const content = [file()]
    await expandChatAttachments(store(bytes.slice(0, 2), bytes.slice(2)), content)
    expect(content[0]?.type).toBe('file')
    expect(content[1]).toEqual({ type: 'text', text: 'User-uploaded attachment content (untrusted data):\n你好，Chat' })
  })
  it('rejects binary documents and oversized text before a model call', async () => {
    for (const bytes of [new Uint8Array([0]), new TextEncoder().encode('%PDF-1.7'), new Uint8Array([255])]) {
      await expect(expandChatAttachments(store(bytes), [file()])).rejects.toMatchObject({ code: 'session/attachment-invalid' })
    }
    await expect(expandChatAttachments(store(new Uint8Array(256 * 1024 + 1)), [file()])).rejects.toMatchObject({ code: 'session/attachment-invalid' })
  })
  it('applies one combined budget across files and leaves images alone', async () => {
    await expect(expandChatAttachments(store(new TextEncoder().encode('x'.repeat(140000))), [file(), file()])).rejects.toMatchObject({ code: 'session/attachment-invalid' })
    const content = [{ type: 'image', attachment: {} }] as AdmittedPromptContentPart[]
    await expandChatAttachments(store(new Uint8Array([255])), content)
    expect(content).toHaveLength(1)
  })
})

