private chatCreation: Promise<void> | undefined

startChat(): Promise<void> {
  if (this.chatCreation !== undefined) return this.chatCreation
  const navigation = AbortSignal.any([this.ctx.layout.beginNavigation(), this.lifetime.signal])
  this.chatCreation = this.sessions.create({ agentPreset: 'deepviewer-chat' }).then(id => {
    if (!navigation.aborted) this.openSession(id)
  }).finally(() => { this.chatCreation = undefined })
  return this.chatCreation
}

async switchMode(mode: 'chat' | 'work'): Promise<void> {
  const list = this.sessions.list.getSnapshot()
  const archived = this.workspaces.list.getSnapshot().archivedSessionIds
  const recent = list.ids.map(id => list.byId[id]).filter((s): s is NonNullable<typeof s> => s !== undefined).filter(s => s.origin !== 'subagent' && !archived.includes(s.id)
    && (s.projectionValues?.agentPreset === 'deepviewer-chat') === (mode === 'chat'))
    .sort((a, b) => b.updatedAt - a.updatedAt)[0]
  this.ctx.layout.beginNavigation()
  if (recent !== undefined) this.openSession(recent.id)
  else if (mode === 'chat') await this.startChat()
  else { this.sessions.clear(); this.ctx.layout.selectPanel(null) }
}

startSession(workspaceId?: WorkspaceId): void {
  const workspace = this.workspaces.list.getSnapshot()
  const sessions = this.sessions.list.getSnapshot()
  const current = sessions.current
  if (workspaceId === undefined && current !== undefined
    && sessions.byId[current]?.projectionValues?.agentPreset === 'deepviewer-chat') {
    void this.startChat().catch(reason => { console.warn('Chat creation failed:', reason) })
    return
  }
  const currentWorkspaceId = current === undefined
    ? undefined
    : workspace.items.find(item => item.sessionIds.includes(current))?.workspaceId
  const recent = workspace.phase === 'ready' && sessions.phase === 'ready'
    ? recentWorkspace(workspace.items, sessions.byId)

