import { useRef, useState } from 'react'
import { IconFolderOpenOutline16, IconNewChatOutline16 } from '@deepseek-ai/dsh-client-ui-primitives'
import type { PropsRuntime, PropsLocale } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from './contract/slots.ts'
import css from './ModeSwitch.module.css'

type Props = PropsRuntime<'sidebar.mode'> & PropsLocale<'workspace'> & {
  switchMode: (mode: 'chat' | 'work') => Promise<void>
}

export function ModeSwitch({ wide, useSessions, switchMode, t }: Props) {
  const isChat = useSessions(s => s.current !== undefined && s.byId[s.current]?.projectionValues?.agentPreset === 'deepviewer-chat')
  const pending = useRef(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const change = async (mode: 'chat' | 'work') => {
    if (pending.current || (mode === 'chat') === isChat) return
    pending.current = true; setBusy(true); setError(null)
    try { await switchMode(mode) } catch (cause) { setError(String(cause)) }
    finally { pending.current = false; setBusy(false) }
  }
  return <div className={wide ? css.root : `${css.root} ${css.rail}`}>
    <div className={css.tabs} role="group" aria-label={t('mode.label')}>
      <button type="button" aria-label="Work" aria-pressed={!isChat} disabled={busy} onClick={() => { void change('work') }}>
        <IconFolderOpenOutline16 size={18} />{wide && <span>Work</span>}
      </button>
      <button type="button" aria-label="Chat" aria-pressed={isChat} disabled={busy} onClick={() => { void change('chat') }}>
        <IconNewChatOutline16 size={18} />{wide && <span>Chat</span>}
      </button>
    </div>
    {error !== null && <div role="alert" className={css.error}>{error}</div>}
  </div>
}

