/** Create only an exclusive child of the desktop-owned projects root. */
private async createManaged(input: unknown): Promise<WorkspaceCreateValue> {
  const root = process.env.DEEPVIEWER_PROJECTS_ROOT
  const name = typeof input === 'string' ? input.trim().normalize('NFC') : ''
  if (!root || !isAbsolute(root)) {
    throw new RemoteError('gateway/bad-request', 'Managed project creation is unavailable on this host', {})
  }
  if (!name || name === '.' || name === '..' || name.startsWith('.')
    || /[\\/:*?"<>|\x00-\x1f\x7f]/u.test(name) || name.endsWith('.')
    || Buffer.byteLength(name) > 200) {
    throw new RemoteError('gateway/bad-request', 'Invalid project name', {})
  }
  if (this.ctx.workspaceRegistry.list().some(workspace => workspace.title === name)) {
    throw new RemoteError('workspace/name-conflict', 'Project name already exists', { name })
  }
  const path = join(root, name)
  let createdDirectory = false
  try {
    await mkdir(root, { recursive: true })
    await mkdir(path)
    createdDirectory = true
    const workspace = await this.ctx.workspaceRegistry.create(path)
    return { workspace: workspaceView(workspace), created: true }
  } catch (error) {
    // Never recursively remove a folder: only undo our own empty directory.
    if (createdDirectory) await rmdir(path).catch(() => {})
    if ((error as NodeJS.ErrnoException)?.code === 'EEXIST') {
      throw new RemoteError('workspace/name-conflict', 'Project folder already exists', { name })
    }
    if (remoteErrorOf(error) !== undefined) throw error
    throw new RemoteError('workspace/invalid-path', 'Could not create project directory', { path }, { cause: error })
  }
}

