/** Recover list classification and titles after cache loss without activating an Agent. */
private async coldProjections(header: SessionHeader, signal?: AbortSignal): Promise<SessionProjectionHints | undefined> {
  signal?.throwIfAborted()
  const cached = this.projectionsFor(header, undefined)
  if (cached?.values.agentPreset !== undefined && cached.values.sessionListMetadata !== undefined) return cached
  try {
