/** DeepViewer: detached Work/Chat classification survives cache loss and restart. */
import { describe, expect, it, vi } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import AgentRegistry from '@deepseek-ai/dsh-agent'
import { agentPresetProjectionDefinition } from '@deepseek-ai/dsh-agent-presets'
import SessionStore, { SESSION_FORMAT_VERSION, SessionId, SessionSeq } from '@deepseek-ai/dsh-session'
import type { SessionHeader, SessionEvent } from '@deepseek-ai/dsh-session'
import SessionProjectionRegistry from '@deepseek-ai/dsh-session-projection'
import { SessionQueryEngine } from '@deepseek-ai/dsh-session-query'
import { createSessionTestRemote, testSessionPersistence } from './test-remote.ts'

const headers: SessionHeader[] = [
  { version: SESSION_FORMAT_VERSION, id: SessionId('work'), createdAt: 1, isSeeded: false, cwd: '/work', agentPreset: 'standard' },
  { version: SESSION_FORMAT_VERSION, id: SessionId('chat'), createdAt: 2, isSeeded: false, agentPreset: 'deepviewer-chat' },
  { version: SESSION_FORMAT_VERSION, id: SessionId('chat-with-cwd'), createdAt: 3, isSeeded: false, cwd: '/work', agentPreset: 'standard' },
]
const defaults = { cwd: '/work', defaultModelSelection: () => ({ provider: 'mock', model: 'mock' }) }
async function mount() {
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  await ctx.plugin(AgentRegistry)
  await ctx.plugin(SessionProjectionRegistry)
  ctx.sessionProjections.register(agentPresetProjectionDefinition)
  const inspect = vi.fn(async (id: SessionId) => {
    const meta = headers.find(h => h.id === id)!
    const rows = [
      ...(id === 'chat-with-cwd' ? [{ type: 'agent-preset/selected', data: { agentPreset: 'deepviewer-chat' } }] : []),
      { type: 'turn/start', data: { turn: 1 } },
      { type: 'user/message', surfaceOp: 'append', data: { id: 'prompt', role: 'user', content: [{ type: 'text', text: 'fixture question' }], source: { kind: 'user' } } },
      { type: 'turn/end', data: { turn: 1, reason: { kind: 'completed' } } },
    ]
    return { meta, events: rows.map((row, seq) => ({ ...row, seq, time: seq + 10 })) as SessionEvent[] }
  })
  ctx.provide('sessionPersistence', testSessionPersistence(ctx, { list: async () => headers, inspect }) as never)
  return { ctx, inspect }
}

describe('DeepViewer cold Work/Chat lists', () => {
  it('rebuilds classification without agents, including cwd-free Chat and a changed preset', async () => {
    for (let boot = 0; boot < 2; boot++) {
      const { ctx, inspect } = await mount()
      try {
        const remote = createSessionTestRemote(ctx, defaults)
        const result = await remote.list({})
        expect(result.ok).toBe(true)
        if (!result.ok) throw new Error('list failed')
        const chats = result.value.items.filter(row => row.projections?.values.agentPreset === 'deepviewer-chat')
        const work = result.value.items.filter(row => row.projections?.values.agentPreset !== 'deepviewer-chat')
        expect(chats.map(row => row.sessionId).sort()).toEqual(['chat', 'chat-with-cwd'])
        expect(work.map(row => row.sessionId)).toEqual(['work'])
        expect(chats.every(row => row.blank === false)).toBe(true)
        expect(inspect).toHaveBeenCalledTimes(3)
        for (const h of headers) {
          expect(ctx.sessions.get(h.id)).toBeUndefined()
          expect(ctx.agents.get(h.id)).toBeUndefined()
        }
      } finally { await ctx.fiber.dispose() }
    }
  })

  it('filters search by reconstructed mode before applying the result limit', async () => {
    const { ctx } = await mount()
    class Query extends SessionQueryEngine {
      override async searchSessions() {
        return { items: headers.map(header => ({ header, live: false, persisted: true,
          bestMatch: { sessionId: header.id, seq: SessionSeq(1), type: 'user/message' as const, time: 10, surface: 'current' as const, snippet: 'fixture question' },
        })) }
      }
      override searchEvents(): Promise<never> { throw new Error('unused') }
    }
    new Query(ctx)
    try {
      const remote = createSessionTestRemote(ctx, defaults)
      const chat = await remote.search({ query: 'fixture', mode: 'chat' })
      const work = await remote.search({ query: 'fixture', mode: 'work' })
      expect(chat).toMatchObject({ ok: true, value: { items: [{ sessionId: 'chat' }, { sessionId: 'chat-with-cwd' }] } })
      expect(work).toMatchObject({ ok: true, value: { items: [{ sessionId: 'work' }] } })
    } finally { await ctx.fiber.dispose() }
  })
})
